#[test]
fn route_division_matches_the_game() {
    for (index, case) in CASES.iter().enumerate() {
        let path: Vec<[f32; 3]> = case.path.iter().map(|p| p.map(f32::from_bits)).collect();
        assert_eq!(planar_length(&path).to_bits(), case.planar_length, "case {index}: planar length");
        let (lengths, total) = segment_lengths(&path);
        for (divisions, expected) in case.divisions {
            let points: Vec<[u32; 3]> = divide_path(&path, &lengths, total, *divisions)
                .iter()
                .map(|p| p.map(f32::to_bits))
                .collect();
            assert_eq!(points, expected.to_vec(), "case {index}: {divisions} divisions");
        }
    }
}
